components.css:
.ds-date-window{padding:23px 0 20px;border-bottom:1px solid var(--line,#d8e0eb)}
.ds-date-window-points{display:grid;grid-template-columns:minmax(0,1fr) 26px minmax(0,1fr);gap:12px;align-items:center}
.ds-date-window-points>div:last-child{text-align:right}
.ds-date-window-label{display:block;color:var(--muted,#5a6879);font-size:11px;margin-bottom:7px}
.ds-date-window time{display:block}
.ds-date-window time strong{font-size:17px;font-weight:590;letter-spacing:-.025em}
.ds-date-window time span{display:block;color:var(--muted,#5a6879);font-size:11px;margin-top:3px}
.ds-date-window-arrow{display:flex;justify-content:center;color:var(--muted,#5a6879)}
.ds-date-window-zone{text-align:center;color:var(--muted,#5a6879);font-size:11px;margin-top:15px}
.ds-date-window-zone>span{margin:0 5px}
.ds-date-window+.ds-entry-summary{border-top:0;margin-top:0}.ds-date-window-points{gap:6px;grid-template-columns:minmax(0,1fr) 20px minmax(0,1fr)}.ds-date-window time strong{font-size:15px}.ds-date-window{font-family:-apple-system,BlinkMacSystemFont,"Helvetica Neue",Arial,sans-serif;font-variant-numeric:tabular-nums;color:var(--ink,#141c28)}
